const fs = require('fs');

const LOG = '/home/x1/Music/.doctum_enviados.json';

const limpar = (v) =>
  v === null || v === undefined ? '' : String(v).replace(/\s+/g, ' ').trim();

const digitos = (v) => {
  let d = String(v ?? '').replace(/\D/g, '');
  if (d.startsWith('55') && d.length > 11) d = d.slice(2);
  return d;
};

const chave = (nome, telefone) => (nome + '|' + telefone).toLowerCase();

let log = [];
try {
  log = JSON.parse(fs.readFileSync(LOG, 'utf8'));
} catch (e) {
  log = [];
}
const jaEnviados = new Set(Array.isArray(log) ? log : []);

const prontos = [];
for (const item of $input.all()) {
  const r = item.json;
  const status = limpar(r['Status de Envio']).toLowerCase();
  if (status !== 'pendente') continue;

  const nome = [limpar(r['Nome']), limpar(r['Sobrenome'])].filter(Boolean).join(' ').trim();
  const telefone = digitos(r['Whatsapp']);
  const curso = limpar(r['Curso']);


  if (nome.length < 3) continue;
  if (telefone.length < 10 || telefone.length > 11) continue;
  if (curso.length < 2) continue;

  if (jaEnviados.has(chave(nome, telefone))) continue;

  prontos.push({ json: { indice: r['Índice'], nome, telefone, curso } });
}
return prontos;

const fs = require('fs');

const LOG = '/home/x1/Music/.doctum_enviados.json';

const limpar = (v) =>
  v === null || v === undefined ? '' : String(v).replace(/\s+/g, ' ').trim();

const digitos = (v) => {
  let d = String(v ?? '').replace(/\D/g, '');
  if (d.startsWith('55') && d.length > 11) d = d.slice(2);
  return d;
};

const chave = (nome, telefone) => (nome + '|' + telefone).toLowerCase();

let log = [];
try {
  log = JSON.parse(fs.readFileSync(LOG, 'utf8'));
} catch (e) {
  log = [];
}
const jaEnviados = new Set(Array.isArray(log) ? log : []);

let enviados = [];
let respostas = [];
try {
  enviados = $('Preparar envios').all();
} catch (e) {
  enviados = [];
}
try {
  respostas = $('Enviar formulário').all();
} catch (e) {
  respostas = [];
}

// Mapa indice da planilha -> resultado do envio (a ordem e preservada pelo no HTTP)
const resultado = new Map();
for (let i = 0; i < enviados.length; i++) {
  const indice = String(enviados[i].json.indice);
  const json = respostas[i]?.json ?? {};
  if (json && json.ok === true) {
    resultado.set(indice, 'Enviado');
  } else {
    let erro = json.error;
    if (erro && typeof erro === 'object') erro = erro.message || JSON.stringify(erro);
    erro = String(erro || json.message || 'falha no envio').slice(0, 120);
    resultado.set(indice, 'Erro: ' + erro);
  }
}

const rows = $('Extrair planilha').all().map((i) => i.json);

const saida = rows.map((r) => {
  const base = { ...r };
  const status = limpar(r['Status de Envio']).toLowerCase();
  if (status !== 'pendente') return { json: base };

  const indice = String(r['Índice']);
  if (resultado.has(indice)) {
    base['Status de Envio'] = resultado.get(indice);
    return { json: base };
  }

  const nome = [limpar(r['Nome']), limpar(r['Sobrenome'])].filter(Boolean).join(' ').trim();
  const telefone = digitos(r['Whatsapp']);
  const curso = limpar(r['Curso']);

  if (jaEnviados.has(chave(nome, telefone))) {
    base['Status de Envio'] = 'Enviado';
  } else if (nome.length < 3) {
    base['Status de Envio'] = 'Erro: nome inválido';
  } else if (telefone.length < 10 || telefone.length > 11) {
    base['Status de Envio'] = 'Erro: telefone inválido';
  } else if (curso.length < 2) {
    base['Status de Envio'] = 'Erro: curso não informado';
  }

  return { json: base };
});

return saida;

const fs = require('fs');

const LOG = '/home/x1/Music/.doctum_enviados.json';

const limpar = (v) =>
  v === null || v === undefined ? '' : String(v).replace(/\s+/g, ' ').trim();

const digitos = (v) => {
  let d = String(v ?? '').replace(/\D/g, '');
  if (d.startsWith('55') && d.length > 11) d = d.slice(2);
  return d;
};

const rows = $('Consolidar status').all().map((i) => i.json);

const porStatus = {};
for (const r of rows) {
  const s = String(r['Status de Envio'] ?? '');
  const chaveStatus = s.startsWith('Erro') ? 'Erro' : (s || 'vazio');
  porStatus[chaveStatus] = (porStatus[chaveStatus] || 0) + 1;
}

// Registra no log quem ja foi enviado, para nao reenviar quando A recriar a planilha
let log = [];
try {
  log = JSON.parse(fs.readFileSync(LOG, 'utf8'));
} catch (e) {
  log = [];
}
const registro = new Set(Array.isArray(log) ? log : []);
for (const r of rows) {
  if (String(r['Status de Envio'] ?? '') !== 'Enviado') continue;
  const nome = [limpar(r['Nome']), limpar(r['Sobrenome'])].filter(Boolean).join(' ').trim();
  registro.add((nome + '|' + digitos(r['Whatsapp'])).toLowerCase());
}
fs.writeFileSync(LOG, JSON.stringify([...registro], null, 2), 'utf8');

return [{
  json: {
    arquivo: '/home/x1/Music/candidatos_indexado.xlsx',
    total: rows.length,
    porStatus,
    jaEnviadosNoTotal: registro.size,
  },
}];
